-- 论文采集结果落库：外部来源幂等、期刊匹配和认领状态可追溯。
BEGIN;

CREATE TABLE IF NOT EXISTS "论文采集结果" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "外部系统编号" bigint NOT NULL,
    "外部论文编号" varchar(200) NOT NULL,
    "论文编号" integer,
    "论文标题" varchar(200) NOT NULL,
    "作者" varchar(2000),
    "刊物名称" varchar(500),
    "ISSN号" varchar(50),
    "CN号" varchar(50),
    "状态" varchar(20) NOT NULL DEFAULT '待认领',
    "原始数据" jsonb NOT NULL DEFAULT '{}'::jsonb,
    "同步批次号" varchar(100),
    "最后同步时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_论文采集结果" PRIMARY KEY ("编号"),
    CONSTRAINT "fk_论文采集结果_系统" FOREIGN KEY ("外部系统编号") REFERENCES "外部系统"("编号"),
    CONSTRAINT "uq_论文采集结果_外部论文" UNIQUE ("外部系统编号", "外部论文编号"),
    CONSTRAINT "ck_论文采集结果_状态" CHECK ("状态" IN ('待认领','已认领','已忽略'))
);

CREATE INDEX IF NOT EXISTS "ix_论文采集结果_状态时间"
    ON "论文采集结果" ("状态", "最后同步时间" DESC);

UPDATE "系统迁移版本"
   SET "版本" = 61,
       "脚本" = '001-061',
       "检查摘要" = '增加论文采集结果幂等落库、期刊匹配和认领状态审计'
 WHERE "编号" = 1;

COMMIT;
